var n=0,r=[];async function o(t){if(t.size>128*1024**2)throw new Error("Image exceeds thumbnail decoding budget. Original remains available.");n>=2&&await new Promise(a=>r.push(a)),n++;let e;try{if(typeof createImageBitmap!="function"||typeof OffscreenCanvas!="function"){if(t.size>16*1024**2)throw new Error("Thumbnail decoding unavailable.");return t}e=await createImageBitmap(t,{resizeWidth:360,resizeQuality:"low"});let a=new OffscreenCanvas(360,240),c=a.getContext("2d"),i=Math.max(360/e.width,240/e.height);return c.drawImage(e,(360-e.width*i)/2,(240-e.height*i)/2,e.width*i,e.height*i),await a.convertToBlob({type:"image/webp",quality:.8})}finally{e?.close(),n--,r.shift()?.()}}export{o as a};
